/*
 * DISK_$PV_MOUNT_INTERNAL - mount or assign a physical volume (and the other
 * members of a striped set)
 *
 * Original address: 0x00E6C2BC (SAU2 map: DISK_$PV_MOUNT_INTERNAL is not
 * exported; Ghidra name; the nested slot finder is at 0x00E6C116)
 * Size: 1418 bytes (0x00E6C2BC .. 0x00E6C84F), constant at 0x00E6C850
 * Generated by: Claude Opus 5.5
 *
 * Callers: DISK_$PV_ASSIGN_N (0x00E6C908, mount type 0 or 1) and
 * DISK_$PV_MOUNT (0x00E6CA2E, mount type 2), both with A5 =
 * DISK_$MOUNT_DATA (0xE826C4); this routine does not load A5 itself.
 *
 * Frame (link.w A6,-0xa8; D2-D7/A2-A4 saved): the ten arguments in
 * disk/disk_internal.h, and
 *   (-0x6A) mask of volume slots claimed (bit = volume index)
 *   (-0x60) the device entry the slot finder / DISK_$MNT_DINIT use
 *   (-0x64) the same for the current striped member
 *   (-0x5C) DBUF_$SET_BUFF's status (never read)
 *   (-0x48) vols[0..7]: the volume index of each member, copied at the end
 *           into part_volx[1..8]
 *   (-0x38) a 16-byte geometry record and (-0x76) a unit-id word handed to
 *           the members' dinit and never read
 *   (-0x28) the first label's pv_uid, (-0x20) its part_dev[0..7]
 *   (-0x72) its interleave, (-0x68) the member's expected part_num,
 *   (-0x8E) the member loop counter, (-0x7A) the member's device
 *   (-0x50) the audit record: unit_type, device, unit; (-0x66) its status
 *           word; (-0x10) an event UID that is never used
 *   D6 the first member's volume index (the result), D7 the member count,
 *   D5 the PV label buffer still held (0 = none), A4 the first descriptor
 *
 * Blocks:
 *   0x00E6C2C4-0x00E6C302  mask = 0; MOUNT_LOCK on; D6 = the slot finder
 *   0x00E6C306-0x00E6C31C  not a mount: PROC2_$SET_CLEANUP(5); then
 *                          disk_$diskless_init
 *   0x00E6C320-0x00E6C38C  descriptor D6 = the template; dev_info, dev_unit,
 *                          part_volx[1] = D6; *status = DISK_$MNT_DINIT
 *   0x00E6C390-0x00E6C3D8  mount_proc, unit_id; not a mount: the caller's
 *                          geometry, mount_state 2, sector_size_code
 *   0x00E6C3DE-0x00E6C416  only mount (2) or assign (1, unit type 0)
 *                          continues: mount_state 1, claim D6, read and
 *                          validate the label
 *   0x00E6C41C-0x00E6C4C6  mount: the label's geometry, uid and sector
 *                          size; unit type 4 or a unit id of 0x3xx:
 *                          DISK_$MNT_DINIT again with the descriptor's own
 *                          cells
 *   0x00E6C4CA-0x00E6C50C  D7 = max(1, label num_parts); keep its uid,
 *                          part_dev, part_num, interleave; release it
 *   0x00E6C510-0x00E6C680  more than one member (unit type 0 only): the
 *                          device must allow striping (0x8002D); member 1
 *                          must be part 1; for each further member: find a
 *                          slot, copy descriptor D6 into it, DISK_$MNT_DINIT,
 *                          read its label, mount_state 4, link it to D6,
 *                          and require the same uid and the next part_num
 *                          (0x8001A otherwise)
 *   0x00E6C684-0x00E6C6A4  release a label still held; failure -> undo
 *   0x00E6C6A8-0x00E6C788  success: descriptor D6 gets mount_state 3
 *                          (mount) or 2, part_volx[1..8], num_parts,
 *                          interleave and the striping masks/shifts,
 *                          blocks_per_cyl, and addr_start / addr_end
 *                          scaled by the member count
 *   0x00E6C78A-0x00E6C7CA  failure: every claimed slot 1..10 is cleared,
 *                          invalidated and its device shut down
 *   0x00E6C7CE-0x00E6C844  MOUNT_LOCK off; audit; return D6
 *
 * Quirks reproduced:
 *   - The audit call always passes AUDIT_$ASSIGN_DISK_EU (0x00E6C838); the
 *     mount/assign choice at 0x00E6C7E6 only fills a local that is never
 *     passed.
 *   - A member's num_parts is set to its part number (0x00E6C62E), and the
 *     member descriptors keep the first member's striping fields.
 *   - The member loop's DISK_$MNT_DINIT writes the member's addr_end, not
 *     addr_start (`pea (-0x38,A2)` 0x00E6C5F2).
 *   - The result is D6 even on failure.
 */

#include "disk/disk_internal.h"
#include "math/math.h"
#include "audit/audit.h"
#include "io/io.h"

/* PROC2_$SET_CLEANUP bit for an assign (`move.w #0x5,-(SP)` 0x00E6C310) */
#define DISK_PVMI_CLEANUP_BIT       5

/* Mount types and descriptor states (0x00E6C306, 0x00E6C3C8, 0x00E6C3F6,
 * 0x00E6C5D2, 0x00E6C624, 0x00E6C6C4/0x00E6C6CC) */
#define DISK_PVMI_MOUNT             2
#define DISK_VOL_STATE_FREE         0
#define DISK_VOL_STATE_CLAIMED      1
#define DISK_VOL_STATE_ASSIGNED     2
#define DISK_VOL_STATE_MOUNTED      3
#define DISK_VOL_STATE_MEMBER       4

/* Volume slots the finder and the undo loop walk (`moveq #0x9` + dbf) */
#define DISK_PVMI_SLOTS             10

/* DBUF_$SET_BUFF release flags for the label (`move.w #0x8` 0x00E6C500) */
#define DISK_PVMI_LABEL_RELEASE     8

/* The device entry's "cannot stripe" bit (`btst.l #0x9` 0x00E6C526) */
#define DISK_PVMI_DEV_NO_STRIPE     0x0200

/* addr_end when the label has none (`move.l #0xffffff` 0x00E6C44C) */
#define DISK_PVMI_NO_END            0x00FFFFFFu

/* unit_type 4 and the 0x3xx unit id that force a re-init on a mount */
#define DISK_PVMI_UNIT_TYPE_4       4
#define DISK_PVMI_UNIT_ID_REINIT    0x0300

/* 0x00E6C850: the audit record's length, `pea (0x24,PC)` at 0x00E6C82A */
static const uint16_t disk_$pvmi_audit_len = 6;

/*
 * The enclosing routine's arguments the nested slot finder reaches through
 * its static link (`movea.l (A6),A2`, 0x00E6C126): (0x08,A2) mount_type,
 * (0x10,A2) .. (0x20,A2) the geometry cells.
 */
typedef struct disk_$pvmi_uplevel_t {
    int16_t    mount_type;
    uint16_t  *unit_id_ptr;
    uint32_t  *num_blocks_ptr;
    uint16_t  *sec_per_track_ptr;
    uint16_t  *num_heads_ptr;
    uint16_t  *pvlabel_info;        /* words: [2] precomp, [3] sectors/block */
} disk_$pvmi_uplevel_t;

/*
 * disk_$pvmi_find_slot - the nested procedure at 0x00E6C116 (260 bytes,
 * link.w A6,-0x14; was FUN_00e6c116)
 *
 * Frame: (0x08) ctype word, (0x0A) cnum word (DISK_$GET_DRTE's two words,
 * the enclosing routine's unit_type and device), (0x0C) unit word (D2),
 * (0x0E) dev_out, (0x12) status (D3); (-0x0A) the slot found.
 *
 *   0x00E6C128-0x00E6C14A  *dev_out = DISK_$GET_DRTE(&ctype, &cnum); none:
 *                          status 0x100001, return 0
 *   0x00E6C14E-0x00E6C1FA  *status = 0; for slots 1..10: a free one
 *                          (mount_state 0) is remembered and the walk goes
 *                          on; a physical-volume slot (lv_start 0) on the
 *                          same device and unit is reported - already
 *                          mounted (mount type 2 and state 3) or in use -
 *                          with its geometry copied back to the uplevel
 *                          cells, and returned
 *   0x00E6C1FE-0x00E6C20C  no slot: status_$volume_table_full
 *
 * Quirk reproduced: the LAST free slot is the one returned.
 */
static int16_t disk_$pvmi_find_slot(const disk_$pvmi_uplevel_t *up,
                                    uint16_t ctype, uint16_t cnum,
                                    uint16_t unit, void **dev_out,
                                    status_$t *status)
{
    int16_t          found;             /* (-0x0A,A6) */
    int16_t          i;                 /* D1w */
    disk_$volume_t  *vol;               /* A1 */

    /* 0x00E6C128-0x00E6C14A */
    *dev_out = DISK_$GET_DRTE(&ctype, &cnum);
    if (*dev_out == NULL) {
        *status = status_$io_controller_not_found;
        return 0;
    }

    /* 0x00E6C14E-0x00E6C1FA */
    *status = status_$ok;
    found = 0;
    for (i = 1; i <= DISK_PVMI_SLOTS; i++) {
        vol = DISK_VOL(i);
        if (vol->mount_state == DISK_VOL_STATE_FREE) {
            found = i;
            continue;
        }
        if (unit != vol->dev_unit || vol->dev_info != *dev_out ||
            vol->lv_start != 0) {
            continue;
        }
        if (up->mount_type == DISK_PVMI_MOUNT &&
            vol->mount_state == DISK_VOL_STATE_MOUNTED) {
            *status = status_$disk_already_mounted;
        } else {
            *status = status_$volume_in_use;
        }
        *up->unit_id_ptr = vol->unit_id;
        *up->num_blocks_ptr = M$MIU$LLW(vol->addr_start, vol->num_parts);
        *up->sec_per_track_ptr = vol->sec_per_track;
        *up->num_heads_ptr = vol->num_heads;
        up->pvlabel_info[3] =
            DISK_$MOUNT_DATA.pow2_table[(int16_t)vol->sector_size_code];
        return i;
    }

    /* 0x00E6C1FE-0x00E6C20C */
    if (found == 0) {
        *status = status_$volume_table_full;
    }
    return found;
}

int16_t DISK_$PV_MOUNT_INTERNAL(int16_t mount_type, int16_t unit_type,
                                 uint16_t device, uint16_t unit,
                                 uint16_t *unit_id_ptr, uint32_t *num_blocks_ptr,
                                 uint16_t *sec_per_track_ptr, uint16_t *num_heads_ptr,
                                 void *pvlabel_info, status_$t *status)
{
    disk_$pvmi_uplevel_t  up;
    uint16_t              vol_mask;         /* (-0x6A,A6) */
    disk_$pv_label_t     *label;            /* D5 */
    void                 *dev_info;         /* (-0x60,A6) */
    void                 *member_dev;       /* (-0x64,A6) */
    status_$t             dbuf_st;          /* (-0x5C,A6) */
    uint16_t              vols[8];          /* (-0x48,A6) */
    uint16_t              member_geom[8];   /* (-0x38,A6) */
    uint16_t              member_unit_id;   /* (-0x76,A6) */
    uid_t                 pv_uid;           /* (-0x28,A6) */
    uint16_t              part_dev[8];      /* (-0x20,A6) */
    uint16_t              interleave;       /* (-0x72,A6) */
    uint16_t              part_expect;      /* (-0x68,A6) */
    uint16_t              members_left;     /* (-0x8E,A6) */
    uint16_t              member_device;    /* (-0x7A,A6) */
    uint16_t              member_unit;      /* D3w */
    int16_t               first;            /* D6w */
    uint16_t              num_parts;        /* D7w */
    int16_t               member;           /* D2w */
    uint16_t              part_num;         /* D2w */
    int16_t               k;                /* (A3 - A6 - 4) / 2 */
    disk_$volume_t       *vol;              /* A4 */
    disk_$volume_t       *mvol;             /* A2 */
    uint16_t             *geom = (uint16_t *)pvlabel_info;
    uint16_t              audit_rec[3];     /* (-0x50,A6) */
    uid_t                 audit_eu;         /* (-0x10,A6), never passed */
    uint16_t              audit_st;         /* (-0x66,A6) */
    int16_t               result;

    up.mount_type = mount_type;
    up.unit_id_ptr = unit_id_ptr;
    up.num_blocks_ptr = num_blocks_ptr;
    up.sec_per_track_ptr = sec_per_track_ptr;
    up.num_heads_ptr = num_heads_ptr;
    up.pvlabel_info = geom;

    /* 0x00E6C2C4-0x00E6C302 */
    vol_mask = 0;
    label = NULL;
    ML_$EXCLUSION_START(&PMAP_$DATA.mount_lock);
    first = disk_$pvmi_find_slot(&up, (uint16_t)unit_type, device, unit,
                                 &dev_info, status);
    if (*status != status_$ok) {
        goto done;
    }

    /* 0x00E6C306-0x00E6C31C */
    if (mount_type != DISK_PVMI_MOUNT) {
        PROC2_$SET_CLEANUP(DISK_PVMI_CLEANUP_BIT);
    }
    disk_$diskless_init();

    /* 0x00E6C320-0x00E6C38C */
    vol = DISK_VOL(first);
    *vol = DISK_$MOUNT_DATA.vol_template;
    vol->dev_info = dev_info;
    vol->dev_unit = unit;
    vol->part_volx[1] = (uint16_t)first;
    num_parts = 1;
    interleave = 0;
    vols[0] = (uint16_t)first;
    *status = DISK_$MNT_DINIT(unit, &dev_info, num_blocks_ptr,
                              sec_per_track_ptr, num_heads_ptr, pvlabel_info,
                              unit_id_ptr);
    if (*status != status_$ok) {
        goto done;
    }

    /* 0x00E6C390-0x00E6C3D8 */
    vol->mount_proc = (int16_t)PROC1_$CURRENT;
    vol->unit_id = *unit_id_ptr;
    if (mount_type != DISK_PVMI_MOUNT) {
        vol->addr_start = *num_blocks_ptr;
        vol->addr_end = *num_blocks_ptr;
        vol->sec_per_track = *sec_per_track_ptr;
        vol->num_heads = *num_heads_ptr;
        vol->mount_state = DISK_VOL_STATE_ASSIGNED;
        vol->sector_size_code =
            DISK_$MOUNT_DATA.log2_table[(int16_t)geom[3]];
    }

    /* 0x00E6C3DE-0x00E6C416 */
    if (mount_type != DISK_PVMI_MOUNT &&
        (mount_type != (int16_t)num_parts || unit_type != 0)) {
        goto done;
    }
    vol->mount_state = num_parts;               /* move.w D7w: 1 */
    vol_mask = (uint16_t)(1u << (first & 31));  /* clr.w / bset.l D6,D1 */
    label = disk_$validate_pv_label(first, status);
    if (*status != status_$ok) {
        goto done;
    }

    /* 0x00E6C41C-0x00E6C4C6 */
    if (mount_type == DISK_PVMI_MOUNT) {
        if (unit_type == DISK_PVMI_UNIT_TYPE_4 &&
            (label->drive_type & 0xFF00) != 0) {
            vol->unit_id = label->drive_type;
        }
        vol->addr_start = label->total_blocks;
        vol->addr_end = label->addr_end;
        if (vol->addr_end == 0) {
            vol->addr_end = DISK_PVMI_NO_END;
        }
        vol->sec_per_track = label->blocks_per_track;   /* one move.l */
        vol->num_heads = label->tracks_per_cyl;
        vol->lv_uid = label->pv_uid;
        vol->sector_size_code =
            DISK_$MOUNT_DATA.log2_table[(int16_t)label->sectors_per_block];
        geom[2] = label->precomp_cyl;
        if (unit_type == DISK_PVMI_UNIT_TYPE_4 ||
            (*unit_id_ptr & 0xFF00) == DISK_PVMI_UNIT_ID_REINIT) {
            *status = DISK_$MNT_DINIT(unit, &dev_info, &vol->addr_start,
                                      &vol->sec_per_track, &vol->num_heads,
                                      pvlabel_info, unit_id_ptr);
            if (*status != status_$ok) {
                goto done;
            }
        }
    }

    /* 0x00E6C4CA-0x00E6C50C */
    if (!(num_parts > label->num_parts)) {      /* cmp.w / bhi */
        num_parts = label->num_parts;
    }
    pv_uid = label->pv_uid;
    for (k = 0; k < 8; k++) {
        part_dev[k] = label->part_dev[k];
    }
    part_num = label->part_num;
    interleave = label->interleave;
    DBUF_$SET_BUFF(label, DISK_PVMI_LABEL_RELEASE, &dbuf_st);
    label = NULL;

    /* 0x00E6C510-0x00E6C536 */
    if (num_parts <= 1 || unit_type != 0) {
        goto done;
    }
    if ((((disk_device_entry_t *)dev_info)->unit_count &
         DISK_PVMI_DEV_NO_STRIPE) != 0) {
        *status = status_$disk_striping_not_supported;
        goto done;
    }

    /* 0x00E6C53A-0x00E6C558 */
    if (part_num != 1) {
        goto bad_label;
    }
    if (num_parts < 2) {                        /* bcs: never true here */
        goto done;
    }
    members_left = (uint16_t)(num_parts - 2);
    part_expect = 2;
    k = 0;

    /* 0x00E6C55C-0x00E6C680: one iteration per further member */
    for (;;) {
        member_device = (uint16_t)((part_dev[k + 1] >> 8) & 0x07);
        member_unit = (uint16_t)((part_dev[k + 1] & 0xF0) >> 4);
        member = disk_$pvmi_find_slot(&up, (uint16_t)unit_type, member_device,
                                      member_unit, &member_dev, status);
        if (*status != status_$ok) {
            goto done;
        }

        /* 0x00E6C59C-0x00E6C5DC */
        mvol = DISK_VOL(member);
        *mvol = *vol;
        mvol->part_volx[1] = (uint16_t)member;
        vols[k + 1] = (uint16_t)member;
        mvol->dev_info = member_dev;
        mvol->dev_unit = member_unit;
        mvol->mount_state = DISK_VOL_STATE_CLAIMED;
        vol_mask |= (uint16_t)(1u << (member & 31));

        /* 0x00E6C5E0-0x00E6C60C */
        *status = DISK_$MNT_DINIT(member_unit, &member_dev, &mvol->addr_end,
                                  &mvol->sec_per_track, &mvol->num_heads,
                                  member_geom, &member_unit_id);
        if (*status != status_$ok) {
            goto done;
        }

        /* 0x00E6C60E-0x00E6C622 */
        label = disk_$validate_pv_label(member, status);
        if (*status != status_$ok) {
            goto done;
        }

        /* 0x00E6C624-0x00E6C650 */
        mvol->mount_state = DISK_VOL_STATE_MEMBER;
        mvol->part_volx[1] = (uint16_t)first;
        mvol->num_parts = part_expect;
        if (label->pv_uid.high != pv_uid.high ||
            label->pv_uid.low != pv_uid.low ||
            part_expect != label->part_num) {
            goto bad_label;
        }

        /* 0x00E6C65E-0x00E6C680 */
        DBUF_$SET_BUFF(label, DISK_PVMI_LABEL_RELEASE, &dbuf_st);
        label = NULL;
        part_expect++;
        k++;
        if (members_left-- == 0) {              /* subq.w #1 / bcc */
            break;
        }
    }
    goto done;

bad_label:
    /* 0x00E6C652-0x00E6C65C */
    *status = status_$invalid_physical_volume_label;

done:
    /* 0x00E6C684-0x00E6C69A */
    if (label != NULL) {
        DBUF_$SET_BUFF(label, DISK_PVMI_LABEL_RELEASE, &dbuf_st);
    }

    if (*status == status_$ok) {
        /* 0x00E6C6A8-0x00E6C6E6 */
        vol = DISK_VOL(first);
        vol->mount_state = (mount_type == DISK_PVMI_MOUNT) ?
                           DISK_VOL_STATE_MOUNTED : DISK_VOL_STATE_ASSIGNED;
        for (k = 0; k < 8; k++) {               /* four move.l */
            vol->part_volx[1 + k] = vols[k];
        }
        vol->num_parts = num_parts;
        vol->part_volx[0] = interleave;

        /* 0x00E6C6EC-0x00E6C732: the jump table at 0x00E6C702
         * (00 0a / 00 14 / 00 34 / 00 18 / 00 24) */
        switch ((uint16_t)(interleave - 1)) {
        case 0:                                 /* 0x00E6C70C */
            vol->stripe_blk_mask = (uint16_t)(num_parts - 1);
            break;
        case 1:                                 /* 0x00E6C716 */
            vol->stripe_vol_mask = (uint16_t)(num_parts - 1);
            break;
        case 2:                                 /* 0x00E6C736 */
            break;
        case 3:                                 /* 0x00E6C71A */
            vol->stripe_blk_mask = 1;
            vol->stripe_vol_mask = (uint16_t)((num_parts >> 1) - 1);
            break;
        case 4:                                 /* 0x00E6C726 */
            vol->stripe_blk_mask = 3;
            vol->stripe_vol_mask = (uint16_t)((num_parts >> 2) - 1);
            break;
        default:                                /* bcc: >= 5 unsigned */
            break;
        }

        /* 0x00E6C736-0x00E6C75C: (0x4a,A5,mask*2) = log2_table[mask + 1] */
        vol->stripe_blk_shift =
            DISK_$MOUNT_DATA.log2_table[(int16_t)vol->stripe_blk_mask + 1];
        vol->stripe_vol_shift =
            DISK_$MOUNT_DATA.log2_table[(int16_t)vol->stripe_vol_mask + 1];
        {
            /* mulu.w then lsr.l D1,D0: the count is taken modulo 64 and a
             * count of 32..63 clears the register */
            uint32_t prod = (uint32_t)vol->num_heads * (uint32_t)vol->sec_per_track;
            uint16_t cnt = (uint16_t)(vol->sector_size_code & 63);
            vol->blocks_per_cyl = (uint16_t)(cnt >= 32 ? 0 : prod >> cnt);
        }

        /* 0x00E6C760-0x00E6C784 */
        vol->addr_start = M$MIU$LLW(vol->addr_start, num_parts);
        vol->addr_end = M$MIU$LLW(vol->addr_end, num_parts);
    } else {
        /* 0x00E6C78A-0x00E6C7CA: undo every claimed slot */
        int16_t i;
        for (i = 1; i <= DISK_PVMI_SLOTS; i++) {
            if (((vol_mask >> i) & 1) != 0) {   /* btst.l D2,D0 */
                mvol = DISK_VOL(i);
                mvol->mount_state = DISK_VOL_STATE_FREE;
                DISK_$INVALIDATE((uint16_t)i);
                DISK_$SHUTDOWN((disk_device_entry_t *)mvol->dev_info,
                               mvol->dev_unit);
            }
        }
    }

    /* 0x00E6C7CE-0x00E6C7DC */
    ML_$EXCLUSION_STOP(&PMAP_$DATA.mount_lock);
    result = first;

    /* 0x00E6C7DE-0x00E6C844 */
    if (AUDIT_$ENABLED < 0) {
        audit_eu = (mount_type == DISK_PVMI_MOUNT) ? AUDIT_$MOUNT_DISK_EU :
                                                     AUDIT_$ASSIGN_DISK_EU;
        (void)audit_eu;
        audit_rec[0] = (uint16_t)unit_type;
        audit_rec[1] = device;
        audit_rec[2] = unit;
        audit_st = (*status == status_$ok) ? 0 : 1;
        AUDIT_$LOG_EVENT(&AUDIT_$ASSIGN_DISK_EU, &audit_st, status,
                         (char *)audit_rec, &disk_$pvmi_audit_len);
    }

    return result;
}
